        [TestMethod]
        public void Records_Should_Never_Have_Null_List_Types()
        {
            var mutableProperties = (from syntaxTree in SyntaxTreesToAnalyze
                                     from @record in syntaxTree.Records
                                     from property in @record.Properties
                                     where property.Type.Contains("Immutable") && (property.Type.Contains("?") || property.SyntaxTree.Contains(" null"))
                                     select new
                                     {
                                         Error = $@"

Any kind of list types have never to be NULL. Any set of data have to be empty or have some elements.
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
FullName:  {@record.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Property:  {property.Type} {property.Name}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Record:

{@record.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:

{@record.ToImmutableListProperties()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                     }).ToImmutableList();

            Assert.IsTrue(mutableProperties.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_R_00004

Any list types have to be initialized and must never be NULL. Findings: '{mutableProperties.Count}':{Environment.NewLine}{mutableProperties.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
